bash -lc $'set -euo pipefail\nroot="$PWD"\nrustup update stable\nscratch=$(mktemp -d /tmp/cx-broad-shard-08.XXXXXX)\ntrap \'rm -rf "$scratch"\' EXIT\npython3 - "$scratch" <<\'SETUP\'\nimport base64,gzip,json,pathlib,sys\nbundle=json.loads(gzip.decompress(base64.b64decode(\'\')))\nout=pathlib.Path(sys.argv[1]);(out/\'probe.py\').write_text(bundle[\'runner\']);(out/\'shard.json\').write_text(bundle[\'manifest\'])\nSETUP\nsha256sum "$scratch/probe.py" "$scratch/shard.json"\ngit -C "$root" -c credential.helper= -c http.extraHeader= fetch https://github.com/BohnBawerick/catallax.git 7cde4119547109994eb685d6ff10187ce0b846fc\ngit clone --no-hardlinks --no-checkout "$root" "$scratch/before"\ngit clone --no-hardlinks --no-checkout "$root" "$scratch/after"\ngit -C "$scratch/before" checkout --detach 7cde4119547109994eb685d6ff10187ce0b846fc --\ngit -C "$scratch/after" checkout --detach 08432eddc566c16c56e62c878c3cff610585f061 --\nexport CARGO_INCREMENTAL=0 CARGO_PROFILE_RELEASE_DEBUG=0 CARGO_TARGET_DIR="$scratch/target"\nproof() {\npython3 - "$scratch/$1.jsonl" "$1" "$2" <<\'PROOF\'\nimport base64,gzip,json,pathlib,sys\np=pathlib.Path(sys.argv[1]);data=p.read_bytes()\nprint(json.dumps({\'kind\':\'full-proof\',\'shard\':8,\'revision\':sys.argv[2],\'code\':int(sys.argv[3]),\'gzip_base64\':base64.b64encode(gzip.compress(data)).decode()}),flush=True)\nfor line in data.decode(errors=\'replace\').splitlines():\n try: row=json.loads(line)\n except ValueError: continue\n if row.get(\'kind\') in (\'configuration\',\'inventory_complete\',\'summary\'):\n  print(json.dumps({\'shard\':8,\'revision\':sys.argv[2],**row}),flush=True)\nPROOF\n}\nbefore=0\n( cd "$scratch/before" && timeout --kill-after=120 9000 python3 -B "$scratch/probe.py" --sha 7cde4119547109994eb685d6ff10187ce0b846fc --release --test-timeout 1800 --shard-manifest "$scratch/shard.json" --shard-phase before ) > "$scratch/before.jsonl" 2>&1 || before=$?\nproof before "$before"\nafter=0\n( cd "$scratch/after" && timeout --kill-after=120 9000 python3 -B "$scratch/probe.py" --sha 08432eddc566c16c56e62c878c3cff610585f061 --release --test-timeout 1800 --shard-manifest "$scratch/shard.json" --shard-phase after ) > "$scratch/after.jsonl" 2>&1 || after=$?\nproof after "$after"\n[ "$before" -eq 0 ] && [ "$after" -eq 0 ]'
